/** Bundle one browser program into the module-loader contract the DSH Web client reads. */
import { build } from 'esbuild'
import { fileURLToPath } from 'node:url'

/** Package id every registration and chunk of this plugin carries. */
export const PACKAGE_ID = '@westwall/dsh-active-markdown'

/** Size ceiling of the entry artifact; chunks are measured separately. */
export const ENTRY_LIMIT = 1.5 * 1024 * 1024

/** Size ceiling of one chunk artifact. */
export const CHUNK_LIMIT = 4 * 1024 * 1024

/** The loader wrapper's first line. */
const HEADER = '// Generated by tools/build-client.mjs; do not edit.\n'

const root = new URL('../', import.meta.url)

/** esbuild options shared by the entry and every chunk. */
const OPTIONS = {
  absWorkingDir: fileURLToPath(root),
  bundle: true,
  format: 'iife',
  platform: 'browser',
  target: ['es2022'],
  jsx: 'transform',
  minify: true,
  external: ['react', '@deepseek-ai/dsh-client-ui-primitives'],
  loader: { '.css': 'text' },
  legalComments: 'inline',
  define: { 'process.env.NODE_ENV': '"production"' },
  charset: 'utf8',
  logOverride: { 'empty-import-meta': 'silent' },
}

/**
 * Bundle one entry file into a self-contained IIFE whose default export is the program's API.
 * @param {string} entryPoint entry path relative to the plugin root, such as `client/src/main.tsx`.
 * @param {string} globalName IIFE global holding the module exports.
 * @returns {Promise<string>} the minified program text, without the loader wrapper.
 */
export async function bundleModule(entryPoint, globalName) {
  const result = await build({ ...OPTIONS, entryPoints: [entryPoint], globalName, write: false })
  const file = result.outputFiles[0]
  if (file === undefined) throw new Error(`client-bundle: esbuild produced no output for ${entryPoint}`)
  return file.text
}

/**
 * Open one registration. The factory hands `require` to an inner function so the
 * bundle's own `"use strict"` directive stays the first statement of its scope,
 * and the bundle reaches the loader through the `__dshRequire` parameter.
 * @param {string | undefined} chunk chunk file name, or undefined for the entry.
 */
function registration(chunk) {
  const field = chunk === undefined ? '' : `  chunk: ${JSON.stringify(chunk)},\n`
  return `window.__ModuleLoader__.load({ id: '${PACKAGE_ID}',\n${field}  factory(require) {\n    return (function (__dshRequire) {\n`
}

/**
 * Close one registration around a program body.
 * @param {string} text the bundled program.
 * @param {string} globalName the IIFE global that program declares.
 */
function closing(text, globalName) {
  return `${text}
    return ${globalName}.default;
    })(require);
  }
});
`
}

/**
 * Wrap the entry program in its registration.
 * @param {string} text {@link bundleModule} output for `client/src/main.tsx`.
 * @param {string} globalName the IIFE global that program declares.
 * @returns {string} the complete `client.js` artifact.
 */
export function wrapEntry(text, globalName) {
  return `${HEADER}${registration(undefined)}${closing(text, globalName)}`
}

/**
 * Wrap one chunk program in its registration, tagged with its file name.
 * @param {string} text {@link bundleModule} output for a chunk entry.
 * @param {string} globalName the IIFE global that chunk declares.
 * @param {string} fileName chunk file name beside `client.js`, such as `client.math.js`.
 * @returns {string} the complete chunk artifact.
 */
export function wrapChunk(text, globalName, fileName) {
  return `${HEADER}${registration(fileName)}${closing(text, globalName)}`
}

/**
 * Reject an artifact over its ceiling, naming the file and the limit.
 * @param {string} fileName artifact path relative to the plugin root.
 * @param {string} text artifact contents.
 * @param {number} limit ceiling in bytes.
 */
export function assertLimit(fileName, text, limit) {
  const bytes = Buffer.byteLength(text)
  if (bytes >= limit) {
    throw new Error(`tools/build-client.mjs: ${fileName} is ${bytes} bytes, over the ${limit}-byte guard`)
  }
}
